def _active_care(self):
        """Which care act is lit in the body right now, if any."""
        try:
            bands = {int(v[0]): k for k, v in self.CARE_ACTIONS.items()}
        except Exception:
            return None
        for band, action in bands.items():
            if float(np.sum(self._tag_cells[96 + band:96 + band + 6])) > 0.05:
                return action
        return None

def _provider_error(resp) -> str | None:
        """Some gateways return a JSON error body with a 200. Read it, don't
        report an empty answer as a mystery."""
        if not isinstance(resp, dict):
            return None
        err = resp.get("error")
        if isinstance(err, dict):
            return f"{err.get('code') or err.get('type')}: " \
                   f"{str(err.get('message'))[:160]}"
        if err:
            return str(err)[:200]
        if resp.get("code") and not resp.get("choices") and not resp.get("content"):
            return f"{resp.get('code')}: {str(resp.get('message'))[:160]}"
        return None

