def _u(self, arousal: float) -> float:
        """Inverted U: 0.2 at both extremes, 1.0 at the optimum."""
        d = (float(arousal) - OPTIMAL_AROUSAL) / U_WIDTH
        return float(np.exp(-0.5 * d * d))

