def suggest(self, sig: str) -> str | None:
        """Highest-confidence known fix (equal confidences break by order
        tried - experience, not convention, will separate them)."""
        e = self.kb.get(sig)
        if not e:
            return None
        fixes = sorted(e["fix_procedures"], key=lambda f: -f["confidence"])
        tried = {a for s, a in self.applied if s == sig}
        for f in fixes:
            if f["action"] not in tried:
                self.applied.append((sig, f["action"]))
                return f["action"]
        return "REWRITE_FROM_CONTEXT"

def connectome_state():
        """PATH A final layer: sandbox, circuit breaker, fast route, context.

        Read-only, and it must stay that way -- the dashboard is not allowed to
        approve its own destructive operations, so approval is a separate
        endpoint a human has to press.
        """
        try:
            a = reasoning_agent()
            cs = a.connectome_stats() if a is not None else {}
        except Exception as exc:
            cs = {"error": f"{type(exc).__name__}: {exc}"[:200]}
        box = dict(cs.get("sandbox") or {})
        try:
            pending = [dict(p, index=i) for i, p in enumerate(
                reasoning_agent().sandbox.pending_approvals[-10:])]
        except Exception:
            pending = []
        box["pending_requests"] = pending
        return {"sandbox": box,
                "circuit_breaker": cs.get("circuit_breaker"),
                "breaker_stats": cs.get("breaker_stats"),
                "fast_route": cs.get("fast_route"),
                "context": cs.get("context"),
                "guarantee": cs.get("guarantee"),
                "ledger_tail": cs.get("ledger_tail"),
                "init_error": cs.get("init_error")}

def start(self, heartbeat: bool = True, train_language: bool = True) -> dict:
        """Bring the periodic processes up. Idempotent; safe to call from
        run_house.py or from a test that drives ticks by hand.

        `heartbeat=False` attaches without arming the timer -- the organ is still
        there and `tick()` still works, which is what "observe nothing on a
        timer" is supposed to mean. `train_language=False` skips the first-run
        lesson loop, which costs real calls.
        """
        out = {"heartbeat": None, "autotraining": None, "language": None}
        if self.heartbeat is None:
            try:
                from organs.heartbeat import Heartbeat
                self.heartbeat = Heartbeat.from_config(self, self.config or {})
                out["heartbeat_attached"] = True
            except Exception as exc:
                out["heartbeat"] = {"error": f"{type(exc).__name__}: {exc}"[:160]}
        hb = self.heartbeat
        if hb is not None and getattr(hb, "agent", None) is None:
            hb.agent = self
        if hb is not None and heartbeat:
            try:
                out["heartbeat"] = hb.start()
            except Exception as exc:
                out["heartbeat"] = {"error": f"{type(exc).__name__}: {exc}"[:160]}
        elif hb is not None:
            out["heartbeat"] = {"started": False, "reason": "heartbeat=False"}
        if self.autotraining is not None:
            try:
                out["autotraining"] = self.autotraining.start()
            except Exception as exc:
                out["autotraining"] = {"error": f"{type(exc).__name__}: {exc}"[:160]}
        if getattr(self, "neural_growth", None) is not None:
            try:
                out["neural_growth"] = self.neural_growth.start()
            except Exception as exc:
                out["neural_growth"] = {"error": f"{type(exc).__name__}: {exc}"[:160]}
        out["language"] = (self._maybe_train_language() if train_language
                           else {"present": self.language is not None,
                                 "trained": False,
                                 "reason": "train_language=False"})
        return out

