def _span(path: Path) -> tuple:
    """(by_line, by_name) -> (first, last) line of each def in the file.

    By name as well as by line, because line numbers drift the first time anyone
    edits the file and the provenance recorded a line.
    """
    try:
        tree = ast.parse(path.read_text(encoding="utf-8"))
    except (OSError, SyntaxError, ValueError):
        return {}, {}
    by_line, by_name = {}, {}
    for node in ast.walk(tree):
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
            span = (int(node.lineno),
                    int(getattr(node, "end_lineno", node.lineno)))
            by_line[int(node.lineno)] = span
            by_name.setdefault(node.name, span)
    return by_line, by_name

def trace_dependencies(self, entity, code: str) -> list[dict]:
        """Every read / write / call site of `entity` in `code`."""
        self.traced += 1
        if isinstance(entity, (list, tuple)):
            out = []
            for e in entity:
                out.extend(self.trace_dependencies(e, code))
            return out
        name = str(entity).strip()
        hits: list[dict] = []
        try:
            tree = ast.parse(code)
        except SyntaxError:
            for i, line in enumerate(code.splitlines()):
                if re.search(rf"\b{re.escape(name)}\b", line):
                    hits.append({"line": i + 1, "type": "text",
                                 "context": line.strip()[:90]})
            return hits
        for node in ast.walk(tree):
            ln = getattr(node, "lineno", None)
            ctx = code.splitlines()[ln - 1].strip()[:90] if ln else ""
            if isinstance(node, ast.Name) and node.id == name:
                kind = ("write" if isinstance(node.ctx, ast.Store)
                        else "read")
                hits.append({"line": ln, "type": kind, "context": ctx})
            elif isinstance(node, ast.Attribute) and node.attr == name:
                hits.append({"line": ln, "type": "attr", "context": ctx})
            elif isinstance(node, ast.FunctionDef) and node.name == name:
                hits.append({"line": ln, "type": "define", "context": ctx})
            elif isinstance(node, ast.Call):
                f = node.func
                fn = f.id if isinstance(f, ast.Name) else \
                    (f.attr if isinstance(f, ast.Attribute) else "")
                if fn == name:
                    hits.append({"line": ln, "type": "call", "context": ctx})
        return hits

