def _score(m: dict) -> dict:
    """A composite, with the parts visible.

    Weighted by what the three goals actually need, and deliberately reported
    alongside its parts: a single number is for comparing two moments in his life,
    never for deciding what to do next.
    """
    v = m.get("vocabulary") or {}
    mem = m.get("memory") or {}
    comp = m.get("comprehension") or {}
    sp = m.get("speech") or {}
    cod = m.get("coding") or {}
    hon = m.get("honesty") or {}

    def frac(a, b):
        return round(float(a or 0) / float(b), 3) if b else 0.0

    parts = {
        # goal 1: speak English
        "language": round(0.4 * min(1.0, float(v.get("words") or 0) / 3000.0)
                          + 0.6 * float(sp.get("multi_word_fraction") or 0.0), 3),
        # goal 1b: understand what is said to him
        "comprehension": round(0.6 * frac(comp.get("corpus_battery"),
                                          comp.get("corpus_battery_total"))
                               + 0.4 * frac(comp.get("novel_phrasings"),
                                            comp.get("novel_total")), 3),
        # goal 3: reasoning -- binding roles is the primitive it is built from
        "binding": _skill(mem.get("role_recovery_sentence"), mem.get("chance")),
        # goal 3b: knowing the limits of what he knows
        "honesty": frac(hon.get("refused_unanswerable"),
                        hon.get("unanswerable_total")),
        # goal 2: code from his own verified library
        "coding": round(0.5 * min(1.0, float(cod.get("library") or 0) / 500.0)
                        + 0.5 * float(cod.get("trusted_fraction") or 0.0), 3),
    }
    weights = {"language": 0.30, "comprehension": 0.20, "binding": 0.20,
               "honesty": 0.10, "coding": 0.20}
    total = round(sum(parts[k] * weights[k] for k in parts), 4)
    return {"composite": total, "weights": weights, "parts": parts}

def write_full_file(self, description, language, template_hint=None,
                        related_code: str = "") -> dict:
        """Greenfield creation: real generator if wired, else scaffold
        composition informed by substrate concepts. Always mechanically
        verified; always honest about which path wrote it."""
        language = str(language or "python").lower()
        desc = str(description or "")
        self.writes[language] = self.writes.get(language, 0) + 1
        code, origin = "", ""
        if self.generator is not None:
            try:
                code = str(self.generator(language, desc,
                                          template_hint or related_code))
                origin = "generator"
            except Exception:
                code = ""
        if not code.strip():
            k = self._knowledge("WRITE_FULL_FILE", desc, "", language)
            if language == "html":
                code = LanguageParadigms.scaffold(
                    "html", "FILE", extra=_title_of(desc),
                    body=_interactive_html(desc))
            elif language == "lua":
                code = LanguageParadigms.scaffold(
                    "lua", "FILE", name="jump_count", extra=_title_of(desc),
                    body=LanguageParadigms.scaffold(
                        "lua", "ADD_FUNCTION", name="jump_count",
                        params="player",
                        body="local n = (player and player.jumps or 0) + 1\n"
                             "if player then player.jumps = n end\n"
                             "return n"))
            elif language == "javascript":
                code = LanguageParadigms.scaffold(
                    "javascript", "FILE", name="main", extra=_title_of(desc),
                    body=LanguageParadigms.scaffold(
                        "javascript", "ADD_FUNCTION", name="main",
                        params="", body="return true;"))
            elif language in ("c", "cpp"):
                code = LanguageParadigms.scaffold(
                    language, "FILE", name="run", extra=_title_of(desc),
                    body=LanguageParadigms.scaffold(
                        language, "ADD_FUNCTION", name="run",
                        params="void", body="return 0;"))
            else:
                code = (f"// {language} file: {desc[:120]}\n"
                        + (related_code or ""))
            origin = "scaffold+knowledge"
            if k["source"] not in ("none", "template"):
                code = code.lstrip()
        v = self.verifier.check(code, language)
        fixes = 0
        while not v["valid"] and fixes < self.max_fix_attempts:
            fixes += 1
            self.fix_attempts += 1
            code = self._repair(code, language, v["error"] or "", "", "")
            v = self.verifier.check(code, language)
            if v["valid"]:
                self.fix_successes += 1
        if language == "python" and code.strip():
            try:
                compile(code, "<full.py>", "exec")
            except SyntaxError as exc:
                return {"ok": False, "success": False, "language": language,
                        "error": f"python scaffold rejected: {exc}"}
        if not v["valid"]:
            return {"ok": False, "success": False, "language": language,
                    "error": f"generated {language} failed verification: "
                             f"{v['error']}", "tool": v.get("tool")}
        return {"ok": True, "success": True, "code": code,
                "language": language, "verified_by": v["tool"],
                "origin": origin, "fixes": fixes}

def write_full_file(self, description, language, template_hint=None,
                        related_code: str = "") -> dict:
        """Greenfield creation: real generator if wired, else scaffold
        composition informed by substrate concepts. Always mechanically
        verified; always honest about which path wrote it."""
        language = str(language or "python").lower()
        desc = str(description or "")
        self.writes[language] = self.writes.get(language, 0) + 1
        code, origin = "", ""
        if self.generator is not None:
            try:
                code = str(self.generator(language, desc,
                                          template_hint or related_code))
                origin = "generator"
            except Exception:
                code = ""
        if not code.strip():
            k = self._knowledge("WRITE_FULL_FILE", desc, "", language)
            if language == "html":
                code = LanguageParadigms.scaffold(
                    "html", "FILE", extra=_title_of(desc),
                    body=_interactive_html(desc))
            elif language == "lua":
                code = LanguageParadigms.scaffold(
                    "lua", "FILE", name="jump_count", extra=_title_of(desc),
                    body=LanguageParadigms.scaffold(
                        "lua", "ADD_FUNCTION", name="jump_count",
                        params="player",
                        body="local n = (player and player.jumps or 0) + 1\n"
                             "if player then player.jumps = n end\n"
                             "return n"))
            elif language == "javascript":
                code = LanguageParadigms.scaffold(
                    "javascript", "FILE", name="main", extra=_title_of(desc),
                    body=LanguageParadigms.scaffold(
                        "javascript", "ADD_FUNCTION", name="main",
                        params="", body="return true;"))
            elif language in ("c", "cpp"):
                code = LanguageParadigms.scaffold(
                    language, "FILE", name="run", extra=_title_of(desc),
                    body=LanguageParadigms.scaffold(
                        language, "ADD_FUNCTION", name="run",
                        params="void", body="return 0;"))
            else:
                code = (f"// {language} file: {desc[:120]}\n"
                        + (related_code or ""))
            origin = "scaffold+knowledge"
            if k["source"] not in ("none", "template"):
                code = code.lstrip()
        v = self.verifier.check(code, language)
        fixes = 0
        while not v["valid"] and fixes < self.max_fix_attempts:
            fixes += 1
            self.fix_attempts += 1
            code = self._repair(code, language, v["error"] or "", "", "")
            v = self.verifier.check(code, language)
            if v["valid"]:
                self.fix_successes += 1
        if language == "python" and code.strip():
            try:
                compile(code, "<full.py>", "exec")
            except SyntaxError as exc:
                return {"ok": False, "success": False, "language": language,
                        "error": f"python scaffold rejected: {exc}"}
        if not v["valid"]:
            return {"ok": False, "success": False, "language": language,
                    "error": f"generated {language} failed verification: "
                             f"{v['error']}", "tool": v.get("tool")}
        return {"ok": True, "success": True, "code": code,
                "language": language, "verified_by": v["tool"],
                "origin": origin, "fixes": fixes}

def process_chat(self, message: str) -> dict:
        """One turn, through the connectome. The human speaks into the
        world; Droso always hears; whether he answers is his own."""
        msg = str(message or "").strip()
        if not msg:
            return {"ok": False, "response": "", "reason": "empty message"}
        if not self._work_lock.acquire(blocking=False):
            return {"ok": False, "reason": "busy",
                    "response": "the connectome is already working on a "
                                "task; this one was not queued"}
        try:
            self.chat_history.append({"role": "user", "content": msg,
                                      "t": time.time()})
            hb = getattr(self.agent, "heartbeat", None)
            if hb is not None:
                try:
                    hb.begin_task(msg)
                    hb.activity("user")
                except Exception:
                    pass
            self.set_status("thinking", msg)
            self.note("user", msg)
            t0 = time.perf_counter()
            lang = getattr(self.agent, "language", None)
            if lang is not None and hasattr(lang, "respond") and \
                    len(msg) <= 80 and not self._looks_like_task(msg):
                reply = None
                try:
                    reply = lang.respond(msg, speaker=str(
                        data.get("speaker") or "you"))
                except Exception as e:
                    import traceback as _tb
                    self.errors.append(("language: " + _tb.format_exc())[:600])
                    print("LANGUAGE ERROR " + _tb.format_exc(), flush=True)
                if reply is None:
                    reply = {"spoken": False, "heard": True,
                             "reason": "the cortex errored; it heard anyway"}
                ms = round((time.perf_counter() - t0) * 1000, 1)
                self.set_status("idle")
                if reply.get("spoken"):
                    self.note("language",
                              f"it heard {msg[:30]!r} and said "
                              f"{reply['utterance']!r} "
                              f"(resonance {reply.get('resonance')})")
                    return {"ok": True, "heard": True, "spoken": True,
                            "response": reply["utterance"], "path": "world",
                            "ms": ms,
                            "oracle_mode": (self.agent.api_oracle.mode
                                            if self.agent.api_oracle
                                            else "absent"),
                            "api_calls": 0,
                            "notes": [reply.get("note", "")],
                            "pool": reply.get("pool"),
                            "resonance": reply.get("resonance"),
                            "mood": reply.get("mood"),
                            "kind": reply.get("kind"),
                            "source": reply.get("source")}
                return {"ok": True, "heard": True, "spoken": False,
                        "response": "", "path": "world", "ms": ms,
                        "oracle_mode": (self.agent.api_oracle.mode
                                        if self.agent.api_oracle
                                        else "absent"),
                        "api_calls": 0,
                        "notes": [reply.get("reason", "it chose not to "
                                            "speak")],
                        "mood": reply.get("mood"),
                        "best_resonance": reply.get("best_resonance"),
                        "pool": reply.get("pool")}
            route = {}
            router = getattr(self.agent, "fast_router", None)
            if router is not None:
                try:
                    route = dict(router.route(msg) or {})
                    self.note("route", f"path={route.get('path')} "
                                       f"why={route.get('why', '')}")
                except Exception as e:
                    self.errors.append(f"router: {type(e).__name__}"[:80])
            out = {}
            try:
                out = self.agent.solve_task(msg) or {}
            except Exception as e:
                self.errors.append(f"solve: {type(e).__name__}"[:80])
                out = {"success": False, "reason": f"{type(e).__name__}: {e}"}
            ms = round((time.perf_counter() - t0) * 1000, 1)
            answer = {"ok": bool(out.get("success", True)),
                      "response": str(out.get("response", "") or ""),
                      "path": route.get("path", "reasoning_loop"),
                      "ms": ms,
                      "oracle_mode": (self.agent.api_oracle.mode
                                      if self.agent.api_oracle else "absent"),
                      "api_calls": int(out.get("api_calls", 0) or 0),
                      "verified": out.get("verified"),
                      "notes": [str(out.get("reason", ""))]
                      if out.get("reason") else [],
                      "meta": {k: out[k] for k in out
                               if k not in ("response",)}
                      }
            if not answer["response"] and out.get("reason"):
                answer["reason"] = str(out.get("reason"))
            self.chat_history.append({"role": "assistant",
                                      "content": answer["response"],
                                      "t": time.time(),
                                      "meta": answer})
            self._teach_from_turn(msg, answer.get("response", ""))
            self.note("done", f"answered in {ms} ms via {answer.get('path')}")
            return answer
        finally:
            if hb is not None:
                try:
                    hb.end_task()
                    hb.tick()
                except Exception:
                    pass
            self.set_status("idle")
            self._work_lock.release()

