        return float(np.dot(self.understand(a), self.understand(b)))

def resolve_sign(label: str | None) -> int | None:
    """Map a raw NT label to a postsynaptic sign; None means 'exclude & count'."""
    return NT_TO_SIGN.get(normalize_nt(label))

def normalize_nt(label: str | None) -> str:
    """Normalize a raw NT label from the CSVs (handles stray quotes/spaces)."""
    if label is None:
        return ""
    return str(label).strip().strip('"').strip().upper()

def pulse(self, idx: np.ndarray, amplitude: float, scale: np.ndarray | None = None) -> None:
        """Inject current into a node subset (goal-slot pulses, sensory drive)."""
        if len(idx) == 0:
            return
        with self._lock:
            self.r[idx] += amplitude * (scale if scale is not None else 1.0)

def _resonance(self, word: str, act: np.ndarray) -> float:
        """How much a word's MEANING lights up under the current semantic
        state. Compared on the WORD cells only -- the body band is context
        for wiring, not part of the language match."""
        if not act.any():
            return 0.0
        wv = self.understand(word)[:INTRO_BASE]
        av = act[:INTRO_BASE]
        na, nv = float(np.linalg.norm(wv)), float(np.linalg.norm(av))
        if na == 0 or nv == 0:
            return 0.0
        return float(np.dot(wv / na, av / nv))

def _lit_now(self, limit: int = 8) -> list:
        """What is lit this moment: the current semantic state spread once and
        ranked. One matvec, not one per word."""
        act = getattr(self, "san_act", None)
        if act is None or not np.any(act):
            return []
        spread = self._spread(np.asarray(act, dtype=np.float32))
        return self._rank_by_spread(spread, limit)

def set_llm_enabled(self, enabled: bool) -> dict:
        """The dashboard's "Enable LLM" switch, in one place.

        Affects the answer oracle only. The teacher keeps its own oracle and its
        own switch (autotraining.enabled), because "stop answering me from the
        internet" and "stop learning" are different requests.
        """
        self.llm_enabled = bool(enabled)
        return {"llm_enabled": self.llm_enabled,
                "oracle_mode": self.api_oracle.mode if self.api_oracle
                else "absent",
                "note": "local memory, procedures and the heartbeat are "
                        "unaffected; tasks needing an oracle come back partial "
                        "with reason llm_disabled"}

