def stem(word) -> str:
    """Fold inflection, and never fold a word into something that is not a word.

    The version this replaces stripped any trailing "s" unless the *base* ended in
    ss/us/is -- so it checked the wrong string and turned "class" into "clas",
    which is the one example its own docstring said must not happen. It also tried
    "es" before "s", so "places" became "plac" while "place" stayed "place" and the
    two could never meet, which is the whole purpose of stemming.

    Under-folding is safe and over-folding is not: two words that stem alike are
    believed to be the same word, and a wrong recall gets believed.
    """
    w = str(word or "").strip().lower()
    if len(w) <= 4:
        return w
    # class, focus, this -- the trailing s is part of the word
    if w.endswith(("ss", "us", "is")):
        return w
    for suf in ("ations", "ing", "ed"):
        if w.endswith(suf) and len(w) - len(suf) > 3:
            return w[:-len(suf)]
    if w.endswith("ies") and len(w) > 5:
        return w[:-3] + "y"                      # memories -> memory
    if w.endswith(("ches", "shes", "ses", "xes", "zes")) and len(w) > 5:
        return w[:-2]                            # watches -> watch
    if w.endswith("s"):
        return w[:-1]                            # places -> place, holds -> hold
    return w

def stem(word) -> str:
    """Fold inflection, and never fold a word into something that is not a word.

    The version this replaces stripped any trailing "s" unless the *base* ended in
    ss/us/is -- so it checked the wrong string and turned "class" into "clas",
    which is the one example its own docstring said must not happen. It also tried
    "es" before "s", so "places" became "plac" while "place" stayed "place" and the
    two could never meet, which is the whole purpose of stemming.

    Under-folding is safe and over-folding is not: two words that stem alike are
    believed to be the same word, and a wrong recall gets believed.
    """
    w = str(word or "").strip().lower()
    if len(w) <= 4:
        return w
    # class, focus, this -- the trailing s is part of the word
    if w.endswith(("ss", "us", "is")):
        return w
    for suf in ("ations", "ing", "ed"):
        if w.endswith(suf) and len(w) - len(suf) > 3:
            return w[:-len(suf)]
    if w.endswith("ies") and len(w) > 5:
        return w[:-3] + "y"                      # memories -> memory
    if w.endswith(("ches", "shes", "ses", "xes", "zes")) and len(w) > 5:
        return w[:-2]                            # watches -> watch
    if w.endswith("s"):
        return w[:-1]                            # places -> place, holds -> hold
    return w

def _function_span(language: str, name: str, code: str) -> tuple | None:
    """(start, end) offsets of the full function text, or None.
    Located on the comment/string-stripped view so prose never fools it."""
    view = _code_view(language, code)
    if language == "lua":
        m = re.search(rf"(?:local\s+)?function\s+{re.escape(name)}\s*\(",
                      view)
        if not m:
            return None
        depth, i = 0, m.start()
        for mm in re.finditer(r"\b(function|if|then|do|end|repeat|until)\b",
                              view[m.start():]):
            w = mm.group(1)
            if w in ("function", "then", "do", "repeat"):
                depth += 1
            elif w in ("end", "until"):
                depth -= 1
                if depth == 0:
                    return (m.start(), m.start() + mm.end())
        return None
    m = re.search(rf"\b{re.escape(name)}\s*\(([^)]*)\)\s*\{{", view)
    if not m:
        m = re.search(rf"(?:function|const|let|var)\s+{re.escape(name)}"
                      r"[^{{=]*=>\s*\{{", view)
    if not m:
        return None
    start = m.start()
    if language in ("c", "cpp"):
        tm = re.search(r"((?:[A-Za-z_][\w:<>&~*]*\s+)+)$", view[:start])
        if tm and tm.group(1).strip():
            start -= len(tm.group(1))
    else:
        km = re.search(r"(?:function|const|let|var)\s+$", view[:start])
        if km:
            start = km.start()
    depth, i = 0, view.index("{", m.end() - 1)
    while i < len(view):
        if view[i] == "{":
            depth += 1
        elif view[i] == "}":
            depth -= 1
            if depth == 0:
                return (start, i + 1)
        i += 1
    return None

