def list_patterns(self, query: str = "", limit: int = 50) -> dict:
        """The pattern library, as rows. Says so when there is no library.

        A panel that shows "0 patterns" when the truth is "no library was
        attached" teaches the reader that the agent has learned nothing, which is
        a different claim from the one the evidence supports.
        """
        lib = self.patterns
        if lib is None:
            return {"present": False, "patterns": [],
                    "note": "no pattern library attached to local_solver"}
        rows: list[dict] = []
        try:
            raw = lib.to_list() if hasattr(lib, "to_list") else []
        except Exception as e:
            return {"present": True, "patterns": [],
                    "note": f"library unreadable: {type(e).__name__}: {e}"}
        q = str(query or "").strip().lower()
        for r in raw or []:
            d = dict(r) if isinstance(r, dict) else {"value": str(r)[:300]}
            hay = " ".join(str(d.get(k, "")) for k in
                           ("key", "trigger_pattern", "value", "name"))
            if q and q not in hay.lower():
                continue
            rows.append(d)
        rows.sort(key=lambda d: float(d.get("confidence", 0) or 0), reverse=True)
        return {"present": True, "total": len(rows),
                "patterns": rows[:max(1, int(limit))]}

def _grounded(self, tag: str, fresh: set, care_now=None) -> bool:
        """Is this phrase TRUE of the world at this moment?"""
        tag = str(tag or "custom")
        if tag == "care":
            return care_now is not None
        if tag.startswith("sel:"):
            return self._state_true(tag[4:])
        if tag in ("day", "night"):
            return tag == self._phase()
        if tag.startswith("event:"):
            return tag[6:] in fresh
        # Lessons saved before grounding existed carry bare tags. Each is mapped
        # to the situation it describes, so an old vocabulary stays honest
        # instead of being spoken at random.
        return {"name": "first" in fresh,
                "welcome": "first" in fresh,
                "human": "user" in fresh,
                "social": "user" in fresh,
                "world": bool(fresh & {"task", "word", "teacher", "oracle"}),
                "home": self.energy < 0.4 or "dusk" in fresh}.get(
                    tag, "first" in fresh)

def _requests(learning, limit: int) -> list:
    """Task text with its rarest word removed -- a phrasing the key never used."""
    from organs.learning_loop import _stem
    n = max(1, len(learning.store))
    df: dict = {}
    for sig in learning.store:
        for w in set(str(sig).split()):
            df[w] = df.get(w, 0) + 1
    out = []
    for sig, rec in learning.store.items():
        task = str(rec.get("task") or "")
        words = re.findall(r"[a-z_][a-z_0-9]{3,}", task.lower())
        if len(words) < 5:
            continue
        rarest = min(words, key=lambda w: df.get(_stem(w), 0))
        ask = " ".join(w for w in words if w != rarest)
        if len(ask.split()) >= 3:
            out.append({"ask": ask, "signature": sig, "dropped": rarest,
                        "confidence": float(rec.get("confidence", 0))})
        if len(out) >= limit:
            break
    return out

def trace_tests() -> dict:
    """One suite run, traced per test node."""
    import contextlib
    import io
    t0 = time.time()
    tr = _PerTestTracer(ROOT.as_posix())
    buf = io.StringIO()
    try:
        # pytest writes to stdout and this tool's report is JSON on stdout;
        # without the redirect the two interleave and cannot be parsed.
        with contextlib.redirect_stdout(buf), contextlib.redirect_stderr(buf):
            rc = pytest.main(["tests", "-q", "--no-header",
                              "--continue-on-collection-errors", "-p",
                              "no:cacheprovider"], plugins=[tr])
    finally:
        sys.settrace(None)
    executed: dict = {}
    for per in tr.hits.values():
        for f, lines in per.items():
            executed.setdefault(f, set()).update(lines)
    return {"hits": tr.hits, "outcome": tr.outcome, "executed": executed,
            "returncode": int(rc), "seconds": round(time.time() - t0, 1),
            "pytest_tail": [l for l in buf.getvalue().splitlines()
                            if l.strip()][-3:]}

def _sequence_seed(self, context: str):
        """The word to open with.

        Preference order matters and the first version got it wrong: it scored
        every sentence-opener he knows against the context and picked the loudest,
        so a reply to "you are not alone" could open with a word that appears
        nowhere in what was said to him. Now the words OF the context come first
        -- a reply should start from what was just heard -- and only if none of
        them can open a sentence does it fall back to resonance over all openers.
        """
        try:
            first = self.sequence.slot_words[0]
        except Exception:
            return None
        if not first:
            return None
        exp = self.live(str(context or ""), learn=False)
        act = exp["act"]
        ctx_words = [w for w in self.tokenizer.tokenize(str(context or ""))
                     if self._speakable(w) and w in first and w in self.word_patterns]
        if ctx_words:
            return max(ctx_words, key=lambda w: self._resonance(w, act))
        cands = [w for w in self.word_patterns
                 if self._speakable(w) and w in first]
        if not cands:
            return None
        return max(cands, key=lambda w: self._resonance(w, act))

def split_requirements(self, text: str) -> list[str]:
        """One string per requirement, order preserved."""
        text = re.sub(r"[ \t]+", " ", str(text or "").strip())
        if not text:
            return []
        chunks = [c.strip() for c in _SPLIT.split(text) if c and c.strip()]
        reqs = [c for c in chunks if _REQ.search(c)]
        if not reqs:
            reqs = chunks or [text]
        out, seen = [], set()
        for r in reqs:
            k = normalise_key(r)
            if k in seen:
                continue
            seen.add(k)
            out.append(r[:400])
            if len(out) >= self.max_parts:
                break
        return out

